const rows=[];for(let i=1;i<q.length;i++){const r=q[i]||[];if(s(r[X.status])!=='QUEUED'){continue;}const sa=s(r[X.send_after]);if(sa&&sa>today){continue;}rows.push({rn:i+1,ask_id:s(r[X.ask_id]),firm:s(r[X.firm]),mb:s(r[X.mb]),thread_id:s(r[X.thread_id]),body:s(r[X.body]),send_after:sa});}
