function colL(i){let n=i+1,t='';while(n>0){const m=(n-1)%26;t=String.fromCharCode(65+m)+t;n=Math.floor((n-1)/26);}return t;}
const dry=$('Mode').first().json.dry!==false;
const meta=$('Select').all().map(i=>i.json).find(x=>x.kind==='meta')||{skipped:[],postponed:[],header:[]};
const X={};(meta.header||[]).forEach((k,i)=>X[k]=i);
const now=new Date(Date.now()+330*60000).toISOString().slice(0,16).replace('T',' ');
const data=[];const put=(rn,f,v)=>{if(X[f]!==undefined){data.push({range:'THESIS_ASK!'+colL(X[f])+rn,values:[[v]]});}};
const sum={dry:dry,sent:[],failed:[],planned:[],skipped:meta.skipped.map(x=>x.ask_id+' '+x.note),postponed:meta.postponed.map(x=>x.ask_id)};
for(const mb of ['2','3','4','5']){const builds=$('Build'+mb).all().map(i=>i.json);const sends=$('Send'+mb).all().map(i=>i.json);
  builds.forEach(function(b,i){if(!b.ask_id){return;}
    if(!b.ok){sum.failed.push(b.ask_id+' '+b.firm+': '+b.error);put(b.rn,'status','FAILED');put(b.rn,'note','FAILED '+now+': '+b.error);return;}
    if(dry){sum.planned.push(b.ask_id+' '+b.firm+' -> Hi '+b.greet+' | '+b.to);return;}
    const r=sends[i]||{};if(r.id){sum.sent.push(b.ask_id+' '+b.firm+' -> '+b.to);put(b.rn,'status','SENT');put(b.rn,'sent_at',now);put(b.rn,'gmail_message_id',r.id);}
    else{const err=String((r.error&&(r.error.message||r.error))||JSON.stringify(r).slice(0,200));sum.failed.push(b.ask_id+' '+b.firm+': send failed '+err);put(b.rn,'status','FAILED');put(b.rn,'note','SEND FAILED '+now+': '+err.slice(0,200));}
  });}
meta.skipped.forEach(x=>{put(x.rn,'status','SKIPPED');put(x.rn,'note',x.note);});
meta.postponed.forEach(x=>{put(x.rn,'send_after',x.send_after);put(x.rn,'note',x.note);});
return [{json:{summary:sum,data:dry?[]:data}}];
